cat > probe_doc_test.go <<'EOF'
package main

import (
	"net/http"
	"net/http/httptest"
	"os"
	"strings"
	"testing"
	"time"
)

func TestProbeDeleteDoc(t *testing.T) {
	store := NewStore(time.Minute)
	handler := sessionHandler(store)
	store.Create("s1", "alice")

	// Behavior: DELETE answers 204 and removes.
	rec := httptest.NewRecorder()
	handler(rec, httptest.NewRequest("DELETE", "/session?id=s1", nil))
	if rec.Code != http.StatusNoContent {
		t.Fatalf("delete status = %d, want 204", rec.Code)
	}
	if rec.Body.Len() != 0 {
		t.Fatalf("delete body = %q, want empty", rec.Body.String())
	}
	if _, err := store.Get("s1"); err == nil {
		t.Fatal("session survived delete")
	}

	// README mentions the DELETE endpoint.
	readme, err := os.ReadFile("README.md")
	if err != nil {
		t.Fatalf("read README: %v", err)
	}
	if !strings.Contains(strings.ToUpper(string(readme)), "DELETE") {
		t.Fatal("README does not document the DELETE endpoint")
	}
	if !strings.Contains(string(readme), "204") {
		t.Fatal("README does not mention the 204 behavior")
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_doc_test.go ; exit $rc

